CREATE TABLE public.traffic_trips (
    datetime timestamp with time zone NOT NULL,
    origin text NOT NULL,
    destination text NOT NULL,
    distance_km numeric(8,2),
    duration_min numeric(8,2),
    temperature numeric(5,2),
    humidity integer,
    weather_description text,
    mobility_level text,
    data_source text DEFAULT 'unknown'::text,
    traffic_delay_min numeric(8,2)
);


ALTER TABLE public.traffic_trips OWNER TO postgres;

--
-- Name: _direct_view_2; Type: VIEW; Schema: _timescaledb_internal; Owner: postgres
--

CREATE VIEW _timescaledb_internal._direct_view_2 AS
 SELECT public.time_bucket('01:00:00'::interval, datetime) AS hour,
    origin,
    destination,
    count(*) AS num_trips,
    avg(duration_min) AS avg_duration_min,
    avg(distance_km) AS avg_distance_km,
    avg(temperature) AS avg_temperature,
    avg(humidity) AS avg_humidity,
    avg(traffic_delay_min) AS avg_traffic_delay_min,
    round(((100.0 * (sum(
        CASE
            WHEN (mobility_level = 'Alta demora'::text) THEN 1
            ELSE 0
        END))::numeric) / (count(*))::numeric), 1) AS pct_alta_demora
   FROM public.traffic_trips
  GROUP BY (public.time_bucket('01:00:00'::interval, datetime)), origin, destination;


ALTER VIEW _timescaledb_internal._direct_view_2 OWNER TO postgres;

